import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<40>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<40>;

    .shared .align 4 .b8 As[1024];
    .shared .align 4 .b8 Bs[1024];

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [N];

    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;

    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %tid.y;
    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ctaid.y;

    mad.lo.s32 %r6, %r5, 16, %r3;   // row
    mad.lo.s32 %r7, %r4, 16, %r2;   // col

    mov.f32 %f1, 0f00000000;

    shr.u32 %r8, %r1, 4;            // N/16, N divisible by 16

    mov.u32 %r9, 0;                 // t

LOOP_START:
    setp.ge.u32 %p1, %r9, %r8;
    @%p1 bra LOOP_END;

    // aCol = t*16+tx ; aIndex = row*N + aCol
    mad.lo.s32 %r10, %r9, 16, %r2;
    mad.lo.s32 %r11, %r6, %r1, %r10;
    mul.wide.s32 %rd10, %r11, 4;
    add.s64 %rd11, %rd4, %rd10;
    ld.global.f32 %f2, [%rd11];

    mad.lo.s32 %r12, %r3, 16, %r2;
    mul.lo.s32 %r13, %r12, 4;
    mov.u32 %r14, As;
    add.s32 %r15, %r14, %r13;
    st.shared.f32 [%r15], %f2;

    // bRow = t*16+ty ; bIndex = bRow*N + col
    mad.lo.s32 %r16, %r9, 16, %r3;
    mad.lo.s32 %r17, %r16, %r1, %r7;
    mul.wide.s32 %rd12, %r17, 4;
    add.s64 %rd13, %rd5, %rd12;
    ld.global.f32 %f3, [%rd13];

    mov.u32 %r18, Bs;
    add.s32 %r19, %r18, %r13;
    st.shared.f32 [%r19], %f3;

    bar.sync 0;

    mov.u32 %r20, 0;
INNER_LOOP:
    setp.ge.u32 %p2, %r20, 16;
    @%p2 bra INNER_END;

    mad.lo.s32 %r21, %r3, 16, %r20;
    mul.lo.s32 %r22, %r21, 4;
    mov.u32 %r23, As;
    add.s32 %r24, %r23, %r22;
    ld.shared.f32 %f4, [%r24];

    mad.lo.s32 %r25, %r20, 16, %r2;
    mul.lo.s32 %r26, %r25, 4;
    mov.u32 %r27, Bs;
    add.s32 %r28, %r27, %r26;
    ld.shared.f32 %f5, [%r28];

    fma.rn.f32 %f1, %f4, %f5, %f1;

    add.u32 %r20, %r20, 1;
    bra INNER_LOOP;
INNER_END:

    bar.sync 0;

    add.u32 %r9, %r9, 1;
    bra LOOP_START;

LOOP_END:

    mad.lo.s32 %r30, %r6, %r1, %r7;
    mul.wide.s32 %rd14, %r30, 4;
    add.s64 %rd15, %rd6, %rd14;
    st.global.f32 [%rd15], %f1;

    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.shape == B.shape and A.shape[0] == A.shape[1], "Inputs must be square matrices of same shape"

        N = A.shape[0]
        A = A.contiguous()
        B = B.contiguous()
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        TILE = 16
        grid = (N // TILE, N // TILE, 1)
        block = (TILE, TILE, 1)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

